from pathlib import Path
import argparse,json,base64,sys

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);a=ap.parse_args();r=a.root.resolve();sys.path.insert(0,str(r/'Scripts'));import officer_art_pipeline as g
    w=json.loads((r/'Art/Officer/work-record.json').read_text(encoding='utf-8'));g.require_plan(r,'front_authoring',w['plans'][w.get('current_review_plan','body-front-v1-review')])
    if w['current_candidate'].get('appearance_review', '').startswith('USER_REJECTED'):
        raise g.Blocked('Rejected body review is historical; do not republish it as a current candidate')
    f=r/'Art/Officer/BodyBaseV1';out=r/'Game/Assets/Trials/OfficerBodyBaseV1'
    bundle=json.loads((f/'candidate-bundle.json').read_text(encoding='utf-8'));g.validate_bundle(r,bundle)
    def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
    assets={k:data(out/v) for k,v in {'body':'body-front.png','skin':'skin-mask.png','edit':'edit-mask.png','preserve':'preserve-mask.png'}.items()}
    # False-color owners from the actual fixed IDs; no fresh segmentation.
    from PIL import Image
    import numpy as np,io
    ids=np.array(Image.open(out/'ownership.png'));rgba=np.zeros((96,64,4),np.uint8)
    for ident in range(1,18):rgba[ids==ident]=(*((np.array([75,117,151])+ident*np.array([51,67,83]))%180+50).tolist(),255)
    stream=io.BytesIO();Image.fromarray(rgba).save(stream,format='PNG');assets['ids']='data:image/png;base64,'+base64.b64encode(stream.getvalue()).decode()
    spec=json.loads((f/'geometry.json').read_text(encoding='utf-8'))
    html='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>百代鏡｜64×96 正面素体</title><style>*{box-sizing:border-box}body{margin:0;background:#1c2931;color:#eee9dc;font:16px/1.8 system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:28px}h1{font-size:26px}h2{font-size:20px;color:#dfbf83}.row{display:flex;gap:36px;flex-wrap:wrap}.native{width:64px;height:96px;image-rendering:pixelated}.large{width:320px;height:480px;image-rendering:pixelated}.frame{display:inline-block;background:#e8e8dd}.checker{background:repeating-conic-gradient(#d8dad2 0 25%,#afb5b0 0 50%) 0/16px 16px}button,select{font:inherit;padding:6px 12px;margin:5px;color:#eee;background:#374b55;border:1px solid #9aa7a8}a{color:#9ed1de}table{border-collapse:collapse}td,th{text-align:left;padding:7px 14px;border-bottom:1px solid #53626b}.note{border-left:3px solid #c9a069;padding:10px 18px;color:#d4cec0}.wide{max-width:100%;height:auto}</style><main><h1>百代鏡｜64×96・1倍の正面素体</h1><p>顔・髪・髭・服・履物なし。骨盤は性器の細部を描かない肌色の面。成人男性の身体を、同じ座標の素体と17部位のマスクとして作成しました。</p><div class="row"><section><h2>通常表示・1倍</h2><div class="frame checker"><canvas id="native" class="native" width="64" height="96"></canvas></div><p>64×96 CSS px<br>拡大表示と同じ実PNG</p></section><section><h2>画素確認・5倍</h2><div id="frame" class="frame"><canvas id="large" class="large" width="64" height="96"></canvas></div></section><section><h2>表示する画像</h2><select id="mode"><option value="body">裸の素体</option><option value="ids">部位ID・17部位</option><option value="skin">肌色マスク</option><option value="edit">生成の編集範囲</option><option value="preserve">生成からの保持範囲</option><option value="landmarks">寸法・関節位置</option></select><p><button data-bg="white">白背景</button><button data-bg="black">黒背景</button><button data-bg="checker">市松背景</button></p><table><tr><th>全身</th><td>84px：y8〜91</td></tr><tr><th>頭部</th><td>21px：y8〜28</td></tr><tr><th>頭身</th><td>4頭身相当の構成値</td></tr><tr><th>透明度</th><td>0 / 255</td></tr><tr><th>部位</th><td>17・再合成差分0</td></tr><tr><th>色</th><td>共通6色パレット内</td></tr></table></section></div><p class="note">輪郭・寸法・顔なし頭部・骨盤・外周を先に固定し、ComfyUIは内部の陰影候補だけに使用しました。生成画像の輪郭や背景をそのまま採用したものではありません。色分けは作者が定義した所属で、人体の自動分割ではありません。</p><h2>今回の検査</h2><p id="checks">実PNGの64×96、部位寸法、二値透過、全身の連結、保持画素、17部位の単体・再合成を確認済み。原寸・拡大・白黒背景で顔/髪/服の残留と身体の接続を点検しました。</p><p>正面静止の確認候補です。側面・背面、動作中の重ね代・隠れ面・接地・歩行は未検証。ユーザーの外見受入はこれからです。</p><details><summary>固定した生成設定</summary><p>ComfyUI / SDXL Base1.0、seed 2026101801、30 steps、CFG 5.5、dpmpp_2m / karras、denoise 0.32、LoRAなし。768×1152の同一座標から固定1/12縮小、個別fitなし。</p></details><p><a href="OFFICER_BODY_BASE_V1.md">制作条件・実測・生成設定の記録</a> ／ <a href="../../Art/Officer/BodyBaseV1/geometry.json">寸法と部位の定義</a> ／ <a href="../../Art/Officer/BodyBaseV1/workflow-api.json">実ワークフロー</a> ／ <a href="../../Art/Officer/BodyBaseV1/validation.json">実画像の検査結果</a></p><script>'''
    html=html.replace('<h2>今回の検査</h2>','<p class="note">生成陰影は固定パレットへの整理後、元の作画との差分0でした。最終画素は、固定した寸法と部位から作画した素体です。生成が見た目を改善したとは扱いません。</p><h2>今回の検査</h2>')
    html+='const assets='+json.dumps(assets)+';const points='+json.dumps(spec['landmarks'])+';'
    html+='''const imgs={};window.bodyReady=false;const canvas=document.getElementById('large');function render(mode='body'){let c=canvas.getContext('2d');c.clearRect(0,0,64,96);c.imageSmoothingEnabled=false;c.drawImage(imgs[mode==='landmarks'?'body':mode],0,0);if(mode==='landmarks'){c.fillStyle='#2c65ff';for(let xy of Object.values(points))c.fillRect(xy[0],xy[1],1,1)}document.getElementById('mode').value=mode;}window.bodyReview={render};(async()=>{await Promise.all(Object.entries(assets).map(async([key,url])=>{let im=new Image;im.src=url;await im.decode();imgs[key]=im}));document.getElementById('native').getContext('2d').drawImage(imgs.body,0,0);document.getElementById('mode').onchange=e=>render(e.target.value);document.querySelectorAll('button[data-bg]').forEach(b=>b.onclick=()=>{let f=document.getElementById('frame');f.className=b.dataset.bg==='checker'?'frame checker':'frame';f.style.background=b.dataset.bg==='checker'?'':b.dataset.bg==='white'?'#e8e8dd':'#141b23'});render();window.bodyReady=true})().catch(e=>{document.getElementById('checks').textContent='表示失敗：'+e.message;throw e});</script></main></html>'''
    (r/'Docs/Proposals/officer-body-base-review.html').write_text(html,encoding='utf-8')
    print('BODY_REVIEW_READY embedded_images=5 native=64x96 large=320x480')

if __name__=='__main__':main()
